<script setup lang="ts">
import { computed, ref } from 'vue'
import { Link, useForm } from '@inertiajs/vue3'
import { ArrowLeft, ArrowRight, Check, Save } from '@lucide/vue'
interface Option { id: number; name: string }
interface Asset { id: number; asset_code: string; category_id: number; description: string; location_id: number; factory_id: number | null; department_id: number; user_name: string | null; user_position: string | null; position_id: number | null; asset_status_id: number; asset_condition_id: number; serial_number: string | null; brand: string | null; acquisition_date: string | null; notes: string | null }
const props = withDefaults(defineProps<{ asset?: Asset; categories: Option[]; locations: Option[]; factories: Option[]; departments: Option[]; positions: Option[]; statuses: Option[]; conditions: Option[] }>(), { asset: undefined })
const step = ref(1)
const editing = Boolean(props.asset)
const form = useForm({ asset_code: props.asset?.asset_code ?? '', category_id: props.asset?.category_id ?? '', description: props.asset?.description ?? '', location_id: props.asset?.location_id ?? '', factory_id: props.asset?.factory_id ?? '', department_id: props.asset?.department_id ?? '', user_name: props.asset?.user_name ?? '', user_position: props.asset?.user_position ?? '', position_id: props.asset?.position_id ?? '', asset_status_id: props.asset?.asset_status_id ?? '', asset_condition_id: props.asset?.asset_condition_id ?? '', serial_number: props.asset?.serial_number ?? '', brand: props.asset?.brand ?? '', acquisition_date: props.asset?.acquisition_date?.slice(0, 10) ?? '', notes: props.asset?.notes ?? '' })
const progress = computed(() => `${Math.round((step.value / 3) * 100)}%`)
function submit(): void { if (editing && props.asset) form.put(route('assets.update', props.asset.id)); else form.post(route('assets.store')) }
</script>
<template><div class="min-h-screen pb-28"><header class="sticky top-0 z-10 border-b bg-white/95 px-4 py-4 backdrop-blur"><div class="mx-auto flex max-w-3xl items-center gap-3"><Link :href="editing && asset ? route('assets.show', asset.id) : route('assets.index')" class="rounded-xl p-2 text-muted-foreground"><ArrowLeft class="size-5" /></Link><div><p class="text-xs uppercase tracking-wider text-primary">Data Aset · Langkah {{ step }} dari 3</p><h1 class="text-xl font-bold">{{ editing ? 'Edit Aset' : 'Tambah Aset' }}</h1></div></div><div class="mx-auto mt-3 h-1.5 max-w-3xl overflow-hidden rounded-full bg-muted"><div class="h-full rounded-full bg-primary transition-all" :style="{ width: progress }"></div></div></header><main class="mx-auto max-w-3xl px-4 py-6"><form @submit.prevent="submit"><section v-show="step === 1" class="space-y-5 rounded-3xl border bg-card p-5"><h2 class="font-semibold">Identitas aset</h2><div><label class="mb-2 block text-sm font-medium">Kode aset</label><input v-model="form.asset_code" class="w-full rounded-xl border px-4 py-3" placeholder="Contoh: AST-0001"><p v-if="form.errors.asset_code" class="mt-1 text-sm text-red-600">{{ form.errors.asset_code }}</p></div><div><label class="mb-2 block text-sm font-medium">Kategori</label><select v-model="form.category_id" class="w-full rounded-xl border px-4 py-3"><option value="">Pilih kategori</option><option v-for="item in categories" :key="item.id" :value="item.id">{{ item.name }}</option></select><p v-if="form.errors.category_id" class="mt-1 text-sm text-red-600">{{ form.errors.category_id }}</p></div><div><label class="mb-2 block text-sm font-medium">Deskripsi atau spesifikasi</label><textarea v-model="form.description" rows="5" class="w-full rounded-xl border px-4 py-3" placeholder="Intel i5, memory 16 GB, untuk server backup"></textarea><p v-if="form.errors.description" class="mt-1 text-sm text-red-600">{{ form.errors.description }}</p></div><div class="grid grid-cols-2 gap-3"><div><label class="mb-2 block text-sm font-medium">Merek <span class="text-muted-foreground">(opsional)</span></label><input v-model="form.brand" class="w-full rounded-xl border px-4 py-3"></div><div><label class="mb-2 block text-sm font-medium">Nomor seri <span class="text-muted-foreground">(opsional)</span></label><input v-model="form.serial_number" class="w-full rounded-xl border px-4 py-3"></div></div></section><section v-show="step === 2" class="space-y-5 rounded-3xl border bg-card p-5"><h2 class="font-semibold">Penempatan dan pengguna</h2><div><label class="mb-2 block text-sm font-medium">Lokasi</label><select v-model="form.location_id" class="w-full rounded-xl border px-4 py-3"><option value="">Pilih lokasi</option><option v-for="item in locations" :key="item.id" :value="item.id">{{ item.name }}</option></select></div><div><label class="mb-2 block text-sm font-medium">Pabrik</label><select v-model="form.factory_id" class="w-full rounded-xl border px-4 py-3"><option value="">Pilih pabrik</option><option v-for="item in factories" :key="item.id" :value="item.id">{{ item.name }}</option></select></div><div><label class="mb-2 block text-sm font-medium">Departemen</label><select v-model="form.department_id" class="w-full rounded-xl border px-4 py-3"><option value="">Pilih departemen</option><option v-for="item in departments" :key="item.id" :value="item.id">{{ item.name }}</option></select></div><div><label class="mb-2 block text-sm font-medium">Nama pengguna <span class="text-muted-foreground">(opsional)</span></label><input v-model="form.user_name" class="w-full rounded-xl border px-4 py-3" placeholder="Muliyono"></div><div><label class="mb-2 block text-sm font-medium">Jabatan <span class="text-muted-foreground">(opsional)</span></label><select v-model="form.position_id" class="w-full rounded-xl border px-4 py-3"><option value="">Pilih jabatan</option><option v-for="item in positions" :key="item.id" :value="item.id">{{ item.name }}</option></select></div></section><section v-show="step === 3" class="space-y-5 rounded-3xl border bg-card p-5"><h2 class="font-semibold">Status dan informasi tambahan</h2><div><label class="mb-2 block text-sm font-medium">Status aset</label><select v-model="form.asset_status_id" class="w-full rounded-xl border px-4 py-3"><option value="">Pilih status</option><option v-for="item in statuses" :key="item.id" :value="item.id">{{ item.name }}</option></select></div><div><label class="mb-2 block text-sm font-medium">Kondisi aset</label><select v-model="form.asset_condition_id" class="w-full rounded-xl border px-4 py-3"><option value="">Pilih kondisi</option><option v-for="item in conditions" :key="item.id" :value="item.id">{{ item.name }}</option></select></div><div><label class="mb-2 block text-sm font-medium">Tanggal perolehan <span class="text-muted-foreground">(opsional)</span></label><input v-model="form.acquisition_date" type="date" class="w-full rounded-xl border px-4 py-3"></div><div><label class="mb-2 block text-sm font-medium">Catatan <span class="text-muted-foreground">(opsional)</span></label><textarea v-model="form.notes" rows="4" class="w-full rounded-xl border px-4 py-3"></textarea></div></section><div v-if="Object.keys(form.errors).length" class="mt-4 rounded-2xl bg-red-50 p-4 text-sm text-red-700">Periksa kembali data yang wajib diisi. Pesan kesalahan tampil pada kolom terkait.</div><div class="fixed inset-x-0 bottom-0 border-t bg-white/95 p-4 backdrop-blur"><div class="mx-auto flex max-w-3xl gap-3"><button v-if="step > 1" type="button" class="flex-1 rounded-xl border px-4 py-3 font-semibold" @click="step--">Kembali</button><button v-if="step < 3" type="button" class="flex flex-1 items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3 font-semibold text-primary-foreground" @click="step++">Lanjut <ArrowRight class="size-4" /></button><button v-else type="submit" :disabled="form.processing" class="flex flex-1 items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3 font-semibold text-primary-foreground"><Save class="size-4" />Simpan aset</button></div></div></form></main></div></template>
